            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (y + dy, x + dx)
                    if (0 <= q[0] < h and 0 <= q[1] < w
                            and q not in seen and grid[q[0]][q[1]] == color):
                        seen.add(q)
                        cells.add(q)
                        stack.append(q)
            comps.append((color, cells))

    # Of repeated-color objects, recolor the larger instance using the
    # color of the prominent L-shaped object.
    def is_l(cells):
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r0 == r1 or c0 == c1:
            return False
        for rr in (r0, r1):
            for cc in (c0, c1):
                shape = ({(rr, x) for x in range(c0, c1 + 1)} |
                         {(y, cc) for y in range(r0, r1 + 1)})
                if cells == shape:
                    return True
        return False

    ls = [(color, cells) for color, cells in comps if is_l(cells)]
    if not ls:
        return [row[:] for row in grid]
    marker_color, _ = max(ls, key=lambda item: len(item[1]))

    by_color = {}
    for color, cells in comps:
        if color != marker_color:
            by_color.setdefault(color, []).append(cells)

    repeated = [(color, cells) for color, groups in by_color.items()
                if len(groups) > 1 for cells in groups]
    if not repeated:
        return [row[:] for row in grid]

    target_color, target = max(repeated, key=lambda item: len(item[1]))
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = marker_color
    return out
